class Solution {
    public int closestFair(int n) {
        long k = n;
        while (true) {
            int len = Long.toString(k).length();
            if (len % 2 == 1) {
                int h = (len + 1) / 2;
                StringBuilder sb = new StringBuilder("1");
                for (int i = 0; i < h; i++) sb.append('0');
                for (int i = 0; i < h - 1; i++) sb.append('1');
                k = Long.parseLong(sb.toString());
                continue;
            }
            int odd = 0, even = 0;
            for (long t = k; t > 0; t /= 10) {
                if ((t % 10) % 2 == 0) even++;
                else odd++;
            }
            if (odd == even) return (int) k;
            k++;
        }
    }
}
